const HIDDEN_GENERIC_FIELDS=new Set(['id','userId','createdAt','updatedAt']);
function genericActiveSheet(page){state.genericTabs=state.genericTabs||{};const cfg=GENERIC_CFG[page];return state.genericTabs[page]||cfg?.tabs?.[0]?.[0]||''}
function genericActualSheet(page,active){if(page==='media'&&['Filmes','Series','Novelas'].includes(active))return 'Midia';if(page==='agenda'&&active==='Semana')return 'Agenda';return active}
function friendlyField(h){return FIELD_LABELS[h]||String(h).replace(/([A-Z])/g,' $1').replace(/^./,m=>m.toUpperCase())}
function genericSelectValues(page,sheet,h){const common={status:['Planejado','Pendente','Em andamento','Concluído','Cancelado','Ativo','Inativo','Pago','A pagar'],priority:['Baixa','Média','Alta'],type:['Receita','Despesa','Livro','Curso','Filme','Série','Novela','Hospedagem','Transporte','Outro'],active:['Sim','Não'],done:['Sim','Não'],favorite:['Sim','Não'],recurring:['Sim','Não'],frequency:['Diário','Semanal','Mensal'],rating:['1','2','3','4','5']};if(h==='type'&&page==='media')return ['Filme','Série','Novela'];if(h==='status'&&page==='media')return ['Quero ver','Assistindo','Pausado','Concluído','Abandonado'];if(h==='category'&&page==='agenda')return ['Pessoal','Trabalho','Saúde','Igreja','Viagem','Treino','Leitura','Outro'];if(h==='module')return MODS.filter(x=>x[0]!=='overview').map(x=>x[2]);return common[h]||null}
function genericSummary(page){const f=FILES[page],t=today();if(page==='agenda'){const a=objRows(f,'Agenda'),tasks=objRows(f,'Tarefas'),r=objRows(f,'Rotinas');return [card('Hoje',a.filter(x=>String(x.date||x.day)===t).length,'compromissos'),card('Pendentes',tasks.filter(x=>!['concluído','concluido','feito'].includes(String(x.status||'').toLowerCase())).length,'tarefas'),card('Rotinas',r.filter(x=>!['não','nao','false','0','inativo'].includes(String(x.active||'').toLowerCase())).length,'ativas')].join('')}
 if(page==='media'){const m=objRows(f,'Midia');return [card('Filmes',m.filter(x=>String(x.type).toLowerCase()==='filme').length,'títulos'),card('Séries',m.filter(x=>String(x.type).toLowerCase()==='série').length,'títulos'),card('Novelas',m.filter(x=>String(x.type).toLowerCase()==='novela').length,'títulos'),card('Em andamento',m.filter(x=>['assistindo','em andamento'].includes(String(x.status||'').toLowerCase())).length,'agora')].join('')}
 if(page==='trips'){const v=objRows(f,'Viagens'),d=objRows(f,'Despesas');const upcoming=v.filter(x=>String(x.endDate||'9999-12-31')>=t&&String(x.status||'').toLowerCase()!=='concluído');return [card('Próximas',upcoming.length,'viagens'),card('Reservas',objRows(f,'Reservas').length,'registros'),card('Despesas',`R$ ${fmt(d.reduce((a,x)=>a+num(x.amount),0))}`,'registradas')].join('')}
 if(page==='integrations'){const i=objRows(f,'Importacoes');return [card('Importações',i.length,'histórico'),card('Importados',i.reduce((a,x)=>a+num(x.recordsImported),0),'registros'),card('Erros',i.reduce((a,x)=>a+num(x.errors),0),'detectados')].join('')}return ''}
function genericRowTitle(page,sheet,o){return o.title||o.name||o.description||o.item||o.place||o.fileName||o.source||friendlyField(sheet)}
function agendaCalendar(){const f=FILES.agenda,items=objRows(f,'Agenda');state.agendaMonthOffset=state.agendaMonthOffset||0;const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+state.agendaMonthOffset);const y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),monthLabel=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(d);let cells='';for(let i=0;i<first;i++)cells+='<div class="cal-cell muted-cell"></div>';for(let day=1;day<=days;day++){const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,ev=items.filter(x=>String(x.date||x.day)===iso);cells+=`<button class="cal-cell ${iso===today()?'today':''}" data-agenda-date="${iso}"><strong>${day}</strong>${ev.slice(0,3).map(x=>`<span>${esc(x.start||'')} ${esc(x.title||'')}</span>`).join('')}${ev.length>3?`<small>+${ev.length-3}</small>`:''}</button>`}return `<div class="calendar-toolbar"><button class="btn" id="prevAgendaMonth">‹</button><h3>${esc(monthLabel)}</h3><button class="btn" id="nextAgendaMonth">›</button></div><div class="calendar-weekdays">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells}</div>`}
function agendaWeek(){const f=FILES.agenda,items=objRows(f,'Agenda');state.agendaWeekOffset=state.agendaWeekOffset||0;const now=new Date();now.setHours(12,0,0,0);const sun=new Date(now);sun.setDate(now.getDate()-now.getDay()+state.agendaWeekOffset*7);const dates=[...Array(7)].map((_,i)=>{const d=new Date(sun);d.setDate(sun.getDate()+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`});return `<div class="calendar-toolbar"><button class="btn" id="prevAgendaWeek">‹</button><h3>${brDate(dates[0])} — ${brDate(dates[6])}</h3><button class="btn" id="nextAgendaWeek">›</button></div><div class="week-agenda">${dates.map((dt,i)=>{const ev=items.filter(x=>String(x.date||x.day)===dt).sort((a,b)=>String(a.start||'').localeCompare(String(b.start||'')));return `<section class="week-day ${dt===today()?'today':''}"><button class="week-day-head" data-agenda-date="${dt}"><strong>${DAYS[i]}</strong><span>${dt.slice(-2)}</span></button>${ev.map(x=>`<button class="week-event" data-generic-edit="${esc(x.id||'')}" data-sheet="Agenda"><strong>${esc(x.start||'')}</strong><span>${esc(x.title||'Compromisso')}</span></button>`).join('')||'<small class="muted">Livre</small>'}</section>`}).join('')}</div>`}
function genericRowsTable(page,sheet){const f=FILES[page],actual=genericActualSheet(page,sheet);if(page==='agenda'&&sheet==='Agenda')return agendaCalendar();if(page==='agenda'&&sheet==='Semana')return agendaWeek();let objs=objRows(f,actual);if(page==='media'&&sheet==='Filmes')objs=objs.filter(x=>String(x.type||'').toLowerCase()==='filme');if(page==='media'&&sheet==='Series')objs=objs.filter(x=>['série','serie'].includes(String(x.type||'').toLowerCase()));if(page==='media'&&sheet==='Novelas')objs=objs.filter(x=>String(x.type||'').toLowerCase()==='novela');const raw=rows(f,actual),headers=(raw[0]||[]).map(String).filter(h=>!HIDDEN_GENERIC_FIELDS.has(h));if(!headers.length)return '<div class="card empty">Estrutura não encontrada.</div>';const visible=headers.slice(0,8);return `<div class="smart-table-wrap"><table class="table smart-table"><thead><tr>${visible.map(h=>`<th>${esc(friendlyField(h))}</th>`).join('')}<th>Ações</th></tr></thead><tbody>${objs.map(o=>`<tr>${visible.map(h=>`<td>${esc(o[h]??'')}</td>`).join('')}<td><div class="row-actions"><button class="btn small" data-generic-edit="${esc(o.id||'')}" data-sheet="${esc(actual)}">Editar</button><button class="btn small danger" data-generic-delete="${esc(o.id||'')}" data-sheet="${esc(actual)}">Excluir</button></div></td></tr>`).join('')||`<tr><td colspan="${visible.length+1}" class="muted">Nenhum registro ainda.</td></tr>`}</tbody></table></div>`}
function generic(page){const cfg=GENERIC_CFG[page],f=FILES[page];if(!cfg)return shell(hero('AF+','Módulo local.'),'AF+');const active=genericActiveSheet(page),actual=genericActualSheet(page,active);const label=cfg.tabs.find(x=>x[0]===active)?.[1]||active;let count=objRows(f,actual).length;if(page==='media'&&active==='Filmes')count=objRows(f,actual).filter(x=>String(x.type||'').toLowerCase()==='filme').length;if(page==='media'&&active==='Series')count=objRows(f,actual).filter(x=>['série','serie'].includes(String(x.type||'').toLowerCase())).length;if(page==='media'&&active==='Novelas')count=objRows(f,actual).filter(x=>String(x.type||'').toLowerCase()==='novela').length;return shell(hero(MODS.find(x=>x[0]===page)?.[2]||page,cfg.subtitle)+`<div class="grid smart-kpis">${genericSummary(page)}</div><div class="module-toolbar"><div class="tabs">${cfg.tabs.map(([id,l])=>`<button class="tab ${active===id?'active':''}" data-gtab="${id}">${l}</button>`).join('')}</div><button class="btn primary" id="genericNew">+ Novo registro</button></div><div class="sectiontitle"><div><span class="body-kicker">${esc(label)}</span><h3>${count} registro(s)</h3></div></div>${genericRowsTable(page,active)}`,MODS.find(x=>x[0]===page)?.[2]||'AF+')}
function genericInput(page,sheet,h,v){const label=friendlyField(h),sel=genericSelectValues(page,sheet,h),low=h.toLowerCase();if(sel)return `<div class="field"><label>${esc(label)}</label><select data-gfield="${esc(h)}"><option value="">Selecione</option>${sel.map(x=>`<option value="${esc(x)}" ${String(v||'')===String(x)?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`;if(['description','notes','content','itinerary','checklist'].includes(h))return `<div class="field full"><label>${esc(label)}</label><textarea data-gfield="${esc(h)}" rows="4">${esc(v||'')}</textarea></div>`;let type='text';if(low.includes('date')||['date','answeredAt','nextCharge','dueDate','startedAt','finishedAt'].includes(h))type='date';else if(['start','end','time'].includes(h))type='time';else if(['amount','balance','limit','currentInvoice','plannedAmount','actualAmount','difference','investedAmount','currentAmount','profitability','totalAmount','paidAmount','remainingAmount','installmentAmount','budget','progress','rating','season','episode','durationMin','intervalDays','goalDays','value','sizeKb','recordsRead','recordsImported','duplicates','errors','closingDay','dueDay','billingDay','currentInstallment','totalInstallments'].includes(h))type='number';else if(h==='month')type='month';return `<div class="field"><label>${esc(label)}</label><input data-gfield="${esc(h)}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(v||'')}"></div>`}
function genericModal(page,sheet,id='',defaults={}){const f=FILES[page],raw=rows(f,sheet),headers=(raw[0]||[]).map(String),objs=objRows(f,sheet),o={...defaults,...(objs.find(x=>String(x.id||'')===String(id))||{})};const fields=headers.filter(h=>!HIDDEN_GENERIC_FIELDS.has(h));state.modal=`<div class="modaltitle"><div><span class="body-kicker">${esc(MODS.find(x=>x[0]===page)?.[2]||page)} • ${esc(GENERIC_CFG[page]?.tabs.find(x=>x[0]===sheet)?.[1]||sheet)}</span><h3>${id?'Editar':'Novo'} registro</h3></div><button class="x" data-close>×</button></div><div class="formgrid smart-form">${fields.map(h=>genericInput(page,sheet,h,o[h])).join('')}</div><div class="actions"><button class="btn" data-close>Cancelar</button><button class="btn primary" id="saveGeneric">Salvar</button></div>`;render();document.getElementById('saveGeneric').onclick=()=>saveGeneric(page,sheet,id)}
async function saveGeneric(page,sheet,id=''){const f=FILES[page],raw=rows(f,sheet),headers=(raw[0]||[]).map(String),objs=objRows(f,sheet),now=new Date().toISOString();let o=objs.find(x=>String(x.id||'')===String(id));if(!o){o={id:`${page}-${sheet.toLowerCase()}-${Date.now()}`,userId:'local',createdAt:now};objs.push(o)}document.querySelectorAll('[data-gfield]').forEach(el=>{o[el.dataset.gfield]=el.value});if(headers.includes('updatedAt'))o.updatedAt=now;if(headers.includes('difference')&&sheet==='Orcamentos')o.difference=num(o.plannedAmount)-num(o.actualAmount);if(headers.includes('remainingAmount')&&sheet==='Dividas')o.remainingAmount=num(o.totalAmount)-num(o.paidAmount);await saveSheet(f,sheet,toRows(objs,headers));state.modal=null;render()}
async function deleteGeneric(page,sheet,id){if(!confirm('Excluir este registro?'))return;const f=FILES[page],raw=rows(f,sheet),headers=(raw[0]||[]).map(String),objs=objRows(f,sheet).filter(x=>String(x.id||'')!==String(id));await saveSheet(f,sheet,toRows(objs,headers));render()}

function objTable(objs){if(!objs.length)return '<div class="card empty">Nenhum registro.</div>';const headers=[...new Set(objs.flatMap(o=>Object.keys(o)))].slice(0,12);return `<div class="tablewrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${objs.map(o=>`<tr>${headers.map(h=>`<td>${esc(typeof o[h]==='object'?JSON.stringify(o[h]):o[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function matrixTable(r){if(!r?.length)return '<div class="card empty">Sem registros.</div>';return `<div class="tablewrap"><table class="table"><thead><tr>${r[0].slice(0,12).map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.slice(1,80).map(row=>`<tr>${r[0].slice(0,12).map((_,i)=>`<td>${esc(row[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>openPage(b.dataset.page));document.getElementById('reload')?.addEventListener('click',()=>load(true));document.getElementById('backup')?.addEventListener('click',async()=>{const r=await fetch('/api/backup');const j=await r.json();toast(`Backup: ${j.files} planilhas`)});document.getElementById('openData')?.addEventListener('click',()=>fetch('/api/open-data'));document.querySelectorAll('[data-ntab]').forEach(b=>b.onclick=()=>{state.nutTab=b.dataset.ntab;render()});document.querySelectorAll('[data-ttab]').forEach(b=>b.onclick=()=>{state.trainTab=b.dataset.ttab;render()});document.querySelectorAll('[data-btab]').forEach(b=>b.onclick=()=>{state.bodyTab=b.dataset.btab;render()});document.getElementById('prevTrainWeek')?.addEventListener('click',()=>{state.trainWeekOffset--;render()});document.getElementById('nextTrainWeek')?.addEventListener('click',()=>{state.trainWeekOffset++;render()});document.querySelectorAll('[data-train-new]').forEach(b=>b.onclick=()=>trainingModal('',{date:b.dataset.trainNew,status:'planejado'}));document.querySelectorAll('[data-train-edit]').forEach(b=>b.onclick=()=>trainingModal(b.dataset.trainEdit));document.getElementById('newTraining')?.addEventListener('click',()=>trainingModal());document.getElementById('newRunTraining')?.addEventListener('click',()=>trainingModal('',{modality:'Corrida',status:'executado'}));document.getElementById('newActivityTraining')?.addEventListener('click',()=>trainingModal('',{modality:'Academia',status:'executado'}));document.getElementById('trainHistoryFilter')?.addEventListener('change',e=>{state.trainHistoryFilter=e.target.value;render()});document.getElementById('trainHistorySource')?.addEventListener('change',e=>{state.trainHistorySource=e.target.value;render()});document.getElementById('trainEvoPeriod')?.addEventListener('change',e=>{state.trainEvoPeriod=e.target.value;render()});document.getElementById('trainImportSource')?.addEventListener('change',e=>{state.trainImportSource=e.target.value});document.getElementById('trainImportFile')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)previewTrainImport(f)});document.getElementById('confirmTrainImport')?.addEventListener('click',confirmTrainImport);document.querySelectorAll('[data-import-link]').forEach(b=>b.onclick=()=>reviewImportedActivity(b.dataset.importLink,'link'));document.querySelectorAll('[data-import-new]').forEach(b=>b.onclick=()=>reviewImportedActivity(b.dataset.importNew,'new'));document.querySelectorAll('[data-import-ignore]').forEach(b=>b.onclick=()=>reviewImportedActivity(b.dataset.importIgnore,'ignore'));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{state.day=+b.dataset.day;render()});document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const [d,m]=b.dataset.plan.split('|');planModal(+d,m)});document.querySelectorAll('[data-consume]').forEach(b=>b.onclick=()=>{const [d,m,mode]=b.dataset.consume.split('|');if(mode==='same')consumeAsPlanned(+d,m);else consumeModal(+d,m)});document.getElementById('directConsume')?.addEventListener('click',directConsumeModal);document.getElementById('editGoals')?.addEventListener('click',goalsModal);document.getElementById('editYesterdaySpend')?.addEventListener('click',()=>gastoModal(dateOffset(-1)));document.querySelectorAll('[data-water]').forEach(b=>b.onclick=()=>addWater(b.dataset.water));document.getElementById('optionSearch')?.addEventListener('input',e=>{state.optionSearch=e.target.value;render()});document.getElementById('optionMealFilter')?.addEventListener('change',e=>{state.optionMealFilter=e.target.value;render()});document.getElementById('addOptionMaster')?.addEventListener('click',()=>optionMasterModal());document.querySelectorAll('[data-edit-option]').forEach(b=>b.onclick=()=>optionMasterModal(b.dataset.editOption));document.querySelectorAll('[data-duplicate-option]').forEach(b=>b.onclick=()=>duplicateOptionMaster(b.dataset.duplicateOption));document.querySelectorAll('[data-delete-option]').forEach(b=>b.onclick=()=>deleteOptionMaster(b.dataset.deleteOption));document.getElementById('foodSearch')?.addEventListener('input',e=>{state.foodSearch=e.target.value;const pos=e.target.selectionStart??state.foodSearch.length;render();setTimeout(()=>{const el=document.getElementById('foodSearch');if(el){el.focus();try{el.setSelectionRange(pos,pos)}catch(_){}}},0)});document.getElementById('foodCategory')?.addEventListener('change',e=>{state.foodCategory=e.target.value;render()});document.getElementById('addFoodMaster')?.addEventListener('click',()=>foodModal(''));document.querySelectorAll('[data-edit-food]').forEach(b=>b.onclick=()=>foodModal(b.dataset.editFood));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{state.modal=null;render()});document.getElementById('modalback')?.addEventListener('click',e=>{if(e.target.id==='modalback'){state.modal=null;render()}});document.querySelectorAll('[data-gtab]').forEach(b=>b.onclick=()=>{state.genericTabs=state.genericTabs||{};state.genericTabs[state.page]=b.dataset.gtab;render()});document.getElementById('genericNew')?.addEventListener('click',()=>{const a=genericActiveSheet(state.page),sh=genericActualSheet(state.page,a),defs=state.page==='media'?{type:a==='Filmes'?'Filme':a==='Series'?'Série':a==='Novelas'?'Novela':''}:{};genericModal(state.page,sh,'',defs)});document.getElementById('prevAgendaMonth')?.addEventListener('click',()=>{state.agendaMonthOffset=(state.agendaMonthOffset||0)-1;render()});document.getElementById('nextAgendaMonth')?.addEventListener('click',()=>{state.agendaMonthOffset=(state.agendaMonthOffset||0)+1;render()});document.getElementById('prevAgendaWeek')?.addEventListener('click',()=>{state.agendaWeekOffset=(state.agendaWeekOffset||0)-1;render()});document.getElementById('nextAgendaWeek')?.addEventListener('click',()=>{state.agendaWeekOffset=(state.agendaWeekOffset||0)+1;render()});document.querySelectorAll('[data-agenda-date]').forEach(b=>b.onclick=()=>genericModal('agenda','Agenda','',{date:b.dataset.agendaDate,status:'Planejado'}));document.querySelectorAll('[data-generic-edit]').forEach(b=>b.onclick=()=>genericModal(state.page,b.dataset.sheet,b.dataset.genericEdit));document.querySelectorAll('[data-generic-delete]').forEach(b=>b.onclick=()=>deleteGeneric(state.page,b.dataset.sheet,b.dataset.genericDelete));if(state.page==='reading')bindReading()}

